queries.logscale:
// LogScale LQL for Mule Account Velocity Pattern
// Repository: flame-banking-transaction-monitoring
// Aggregation that cannot be expressed in Sigma:
// Original condition: selection_inbound | count(distinct originator_name) by account_id > 3
transaction_type="ACH_IN"
| groupBy(account_id, function=[count(as=event_count), collect(originator_name)])
| event_count > 3

// LogScale LQL for Infostealer Credential Dump Velocity
// Repository: flame-banking-endpoint-detection
// Aggregation that cannot be expressed in Sigma:
// Original condition: selection and not filter_legitimate | count(distinct target_credential) by host_id > 20
event_type="credential_access"
action="credential_read"
(process_name="\lsass.exe" OR process_name="\services.exe")
| groupBy(host_id, function=[count(as=event_count), collect(target_credential)])
| event_count > 20

// LogScale LQL for Credential Testing After Dump
// Repository: flame-banking-auth-logs
// Aggregation that cannot be expressed in Sigma:
// Original condition: selection | count(distinct user_id) by source_ip > 10
event_type="login_attempt"
(auth_result="failure" OR auth_result="success")
| groupBy(source_ip, function=[count(as=event_count), collect(user_id)])
| event_count > 10

// LogScale LQL for Multiple Account Access from Single Source
// Repository: flame-banking-auth-logs
// Aggregation that cannot be expressed in Sigma:
// Original condition: selection | count(distinct account_id) by source_ip > 5 or selection | count(distinct account_id) by device_fingerprint > 3
event_type="login_success"
| groupBy(source_ip, function=[count(as=event_count), collect(account_id)])
| event_count > 5
| groupBy(device_fingerprint, function=[count(as=event_count), collect(account_id)])
| event_count > 3

// LogScale LQL for Stolen Session Token Replay
// Repository: flame-banking-auth-logs
// Aggregation that cannot be expressed in Sigma:
// Original condition: selection and not filter_same_context | count() by session_token > 1
event_type="session_activity"
session_token=true
geo_country="%original_session_country%"
device_fingerprint="%original_device_fingerprint%"
| groupBy(session_token, function=count(as=event_count))
| event_count > 1

// LogScale LQL for Login Velocity Anomaly
// Repository: flame-banking-auth-logs
// Aggregation that cannot be expressed in Sigma:
// Original condition: selection and not filter_internal | count() by source_ip > 50
event_type="login_attempt"
(source_ip="10.0.0.0/8" OR source_ip="172.16.0.0/12" OR source_ip="192.168.0.0/16")
| groupBy(source_ip, function=count(as=event_count))
| event_count > 50

// LogScale LQL for Geographic Impossibility Login
// Repository: flame-banking-auth-logs
// Aggregation that cannot be expressed in Sigma:
// Original condition: selection | near by user_id | where geo_distance(src.geo_lat, src.geo_lon, dst.geo_lat, dst.geo_lon) > 1000 and time_diff < 60m
(event_type="login_success" OR event_type="login_attempt")
// Temporal correlation — use join() or selfJoinFilter() in LogScale
// to correlate the selection events within the timeframe
| selfJoinFilter(user_id, where=[...])

// LogScale LQL for Device Fingerprint Anomaly
// Repository: flame-banking-web-gateway
// Aggregation that cannot be expressed in Sigma:
// Original condition: selection | where device_fingerprint in known_device_fingerprints and (
  os_version != baseline.os_version
  or screen_resolution != baseline.screen_resolution
  or timezone_offset != baseline.timezo
event_type="session_start"
device_fingerprint=true
// Aggregation logic from original condition:
// selection | where device_fingerprint in known_device_fingerprints and (
  os_version != baseline.os_version
  or screen_resolution != baseline.screen_resolution
  or timezone_offset != baseline.timezone_offset
  or webgl_renderer != baseline.webgl_renderer
  or canvas_hash != baseline.canvas_hash
)

// LogScale LQL for Combo List Iteration Pattern
// Repository: flame-banking-auth-logs
// Aggregation that cannot be expressed in Sigma:
// Original condition: selection | count(distinct username) by source_ip > 15 and stddev(inter_event_time) by source_ip < 500ms
event_type="login_attempt"
auth_result="failure"
| groupBy(source_ip, function=[count(as=event_count), collect(username)])
| event_count > 15

// LogScale LQL for Distributed Credential Stuffing
// Repository: flame-banking-auth-logs
// Aggregation that cannot be expressed in Sigma:
// Original condition: selection and selection_characteristics | count(distinct source_ip) by user_agent > 20 and count(distinct username) by user_agent > 50 and max(count() by source_ip) < 5
event_type="login_attempt"
auth_result="failure"
user_agent=/^Mozilla/5\.0.*$/
| groupBy(user_agent, function=[count(as=event_count), collect(source_ip)])
| event_count > 20
| groupBy(user_agent, function=[count(as=event_count), collect(username)])
| event_count > 50

// LogScale LQL for Credential Spray Single Password
// Repository: flame-banking-auth-logs
// Aggregation that cannot be expressed in Sigma:
// Original condition: selection | count(distinct username) by password_hash > 20 and count(distinct password_hash) by source_ip < 3
event_type="login_attempt"
auth_result="failure"
| groupBy(password_hash, function=[count(as=event_count), collect(username)])
| event_count > 20
| groupBy(source_ip, function=[count(as=event_count), collect(password_hash)])
| event_count < 3

// LogScale LQL for Beneficiary Change Velocity Anomaly
// Repository: flame-banking-core-banking
// Aggregation that cannot be expressed in Sigma:
// Original condition: selection | count(distinct beneficiary_id) by account_id > 3
(event_type="BENEFICIARY_ADD" OR event_type="BENEFICIARY_MODIFY" OR event_type="BENEFICIARY_DELETE")
| groupBy(account_id, function=[count(as=event_count), collect(beneficiary_id)])
| event_count > 3

// LogScale LQL for Rapid Contact Information Change
// Repository: flame-banking-identity-management
// Aggregation that cannot be expressed in Sigma:
// Original condition: (selection_email and selection_phone and selection_address) | count() by account_id >= 3
event_type="CONTACT_CHANGE"
field_changed="email"
event_type="CONTACT_CHANGE"
field_changed="phone"
event_type="CONTACT_CHANGE"
field_changed="mailing_address"
| groupBy(account_id, function=count(as=event_count))
| event_count >= 3

// LogScale LQL for MFA Method Switch Before High-Value Transaction
// Repository: flame-banking-identity-management
// Aggregation that cannot be expressed in Sigma:
// Original condition: selection_mfa_change | near selection_high_value_txn by account_id
event_type="MFA_METHOD_CHANGE"
(new_mfa_method="sms_otp" OR new_mfa_method="email_otp" OR new_mfa_method="voice_call")
(event_type="WIRE_INITIATION" OR event_type="ACH_DEBIT")
transaction_amount>=5000
// Temporal correlation — use join() or selfJoinFilter() in LogScale
// to correlate the selection events within the timeframe
| selfJoinFilter(account_id, where=[...])

// LogScale LQL for Split Transfer Chain Detection
// Repository: flame-banking-wire-system
// Aggregation that cannot be expressed in Sigma:
// Original condition: selection_large_inbound | near selection_multiple_outbound by account_id | count(distinct beneficiary_id) by account_id > 2
(event_type="WIRE_CREDIT" OR event_type="ACH_CREDIT")
transaction_amount>=25000
(event_type="WIRE_INITIATION" OR event_type="ACH_DEBIT" OR event_type="INTERNAL_TRANSFER")
transaction_amount<10000
| groupBy(account_id, function=[count(as=event_count), collect(beneficiary_id)])
| event_count > 2

// LogScale LQL for Rapid Outbound Wire After Large Inbound
// Repository: flame-banking-transaction-monitoring
// Aggregation that cannot be expressed in Sigma:
// Original condition: selection_inbound | near selection_outbound by account_id
(event_type="WIRE_CREDIT" OR event_type="ACH_CREDIT")
transaction_amount>=10000
(event_type="WIRE_INITIATION" OR event_type="ACH_DEBIT")
transaction_amount>=8000
// Temporal correlation — use join() or selfJoinFilter() in LogScale
// to correlate the selection events within the timeframe
| selfJoinFilter(account_id, where=[...])

// LogScale LQL for Round-Dollar Wire Amount Pattern
// Repository: flame-banking-wire-system
// Aggregation that cannot be expressed in Sigma:
// Original condition: selection | count() by account_id > 4
event_type="WIRE_INITIATION"
transaction_amount>=1000
transaction_amount_is_round=true
| groupBy(account_id, function=count(as=event_count))
| event_count > 4

// LogScale LQL for ACH Return Rate Anomaly
// Repository: flame-banking-ach-processing
// Aggregation that cannot be expressed in Sigma:
// Original condition: selection_returns | count() by originator_id > 5
event_type="ACH_RETURN"
(return_code="R10" OR return_code="R29" OR return_code="R07" OR return_code="R08")
| groupBy(originator_id, function=count(as=event_count))
| event_count > 5

// LogScale LQL for Payment Instruction Velocity Spike
// Repository: flame-banking-transaction-monitoring
// Aggregation that cannot be expressed in Sigma:
// Original condition: selection | count() by session_id > 5
(event_type="WIRE_INITIATION" OR event_type="ACH_BATCH_SUBMIT" OR event_type="INTERNAL_TRANSFER" OR event_type="PAYMENT_INSTRUCTION")
aggregate="sum(transaction_amount) by account_id"
threshold_multiplier="3.0"
| groupBy(session_id, function=count(as=event_count))
| event_count > 5

// LogScale LQL for Mule Rapid ATM Withdrawal After Inbound Transfer
// Repository: flame-banking-transaction-monitoring
// Aggregation that cannot be expressed in Sigma:
// Original condition: selection_inbound | near selection_atm_withdrawal by account_id
(event_type="WIRE_CREDIT" OR event_type="ACH_CREDIT")
transaction_amount>=2000
event_type="ATM_WITHDRAWAL"
transaction_amount>=500
// Temporal correlation — use join() or selfJoinFilter() in LogScale
// to correlate the selection events within the timeframe
| selfJoinFilter(account_id, where=[...])

// LogScale LQL for Account Age vs Transaction Volume Mismatch
// Repository: flame-banking-transaction-monitoring
// Aggregation that cannot be expressed in Sigma:
// Original condition: selection and selection_high_volume | count() by account_id > 20
account_age_days<90
(event_type="WIRE_CREDIT" OR event_type="ACH_CREDIT" OR event_type="WIRE_INITIATION" OR event_type="ACH_DEBIT" OR event_type="INTERNAL_TRANSFER")
peer_comparison="{'metric': 'transaction_count', 'threshold': 'percentile_95'}"
| groupBy(account_id, function=count(as=event_count))
| event_count > 20

// LogScale LQL for Multi-Bank Funnel Pattern
// Repository: flame-banking-transaction-monitoring
// Aggregation that cannot be expressed in Sigma:
// Original condition: selection_inbound | count(distinct originating_bank_id) by account_id > 3 and selection_outbound | count(distinct beneficiary_id) by account_id <= 2
(event_type="WIRE_CREDIT" OR event_type="ACH_CREDIT")
originating_bank_external=true
(event_type="WIRE_INITIATION" OR event_type="ACH_DEBIT")
| groupBy(account_id, function=[count(as=event_count), collect(originating_bank_id)])
| event_count > 3
| groupBy(account_id, function=[count(as=event_count), collect(beneficiary_id)])
| event_count <= 2

// LogScale LQL for Crypto Off-Ramp After Wire or ACH Receipt
// Repository: flame-banking-transaction-monitoring
// Aggregation that cannot be expressed in Sigma:
// Original condition: selection_inbound | near selection_crypto_outbound by account_id
(event_type="WIRE_CREDIT" OR event_type="ACH_CREDIT")
transaction_amount>=1000
(event_type="WIRE_INITIATION" OR event_type="ACH_DEBIT")
beneficiary_category="crypto_exchange"
(beneficiary_name="Coinbase" OR beneficiary_name="Binance" OR beneficiary_name="Kraken" OR beneficiary_name="FTX" OR beneficiary_name="Gemini" OR beneficiary_name="Crypto.com" OR beneficiary_name="Bitfinex")
// Temporal correlation — use join() or selfJoinFilter() in LogScale
// to correlate the selection events within the timeframe
| selfJoinFilter(account_id, where=[...])

// LogScale LQL for Peer-to-Peer Transfer Chain (Smurfing Pattern)
// Repository: flame-banking-transaction-monitoring
// Aggregation that cannot be expressed in Sigma:
// Original condition: selection_p2p | count() by account_id > 3 and selection_chain | count(distinct counterparty_account_id) by account_id > 2
(event_type="P2P_TRANSFER" OR event_type="INTERNAL_TRANSFER" OR event_type="ZELLE_SEND" OR event_type="VENMO_TRANSFER")
transaction_amount>=500
inbound_event="P2P_CREDIT"
outbound_event="P2P_DEBIT"
| groupBy(account_id, function=[count(as=event_count), collect(counterparty_account_id)])
| event_count > 2

// LogScale LQL for Mule Recruitment Test Deposit Pattern
// Repository: flame-banking-ach-processing
// Aggregation that cannot be expressed in Sigma:
// Original condition: selection_small_deposits | count(distinct originator_id) by account_id > 8
(event_type="ACH_CREDIT" OR event_type="P2P_CREDIT" OR event_type="WIRE_CREDIT")
transaction_amount<=100
transaction_amount>=1
| groupBy(account_id, function=[count(as=event_count), collect(originator_id)])
| event_count > 8

// LogScale LQL for Rapid Fund Layering Through Shell Accounts
// Repository: flame-banking-transaction-monitoring
// Aggregation that cannot be expressed in Sigma:
// Original condition: selection_pass_through | near selection_rapid_egress by account_id and selection_low_retention | count() by account_id > 3 within 30d
(event_type="WIRE_CREDIT" OR event_type="ACH_CREDIT" OR event_type="INTERNAL_TRANSFER_IN")
transaction_amount>=5000
(event_type="WIRE_INITIATION" OR event_type="ACH_DEBIT" OR event_type="INTERNAL_TRANSFER_OUT")
post_transaction_balance<=500
| groupBy(account_id, function=count(as=event_count))
| event_count > 3

// LogScale LQL for Carrier Change Authentication Correlation
// Repository: flame-telecom-identity-management
// Aggregation that cannot be expressed in Sigma:
// Original condition: selection_carrier_change | followed_by selection_auth on phone_number within 120m
(event_type="sim_swap" OR event_type="carrier_change" OR event_type="number_port")
status="completed"
event_type="login_attempt"
mfa_method="sms"
mfa_result="success"
// Sequential correlation — use LogScale sequence detection
// Correlate stages sequentially on phone_number within 120m

// LogScale LQL for MFA Push Bombing
// Repository: flame-banking-mfa-logs
// Aggregation that cannot be expressed in Sigma:
// Original condition: selection | count() by user_id > 5 and count(selection_denied) by user_id > 3
event_type="mfa_push_sent"
mfa_method="push"
(mfa_result="denied" OR mfa_result="timeout" OR mfa_result="ignored")
| groupBy(user_id, function=count(as=event_count))
| event_count > 5

// LogScale LQL for SIM Swap Indicator Chain
// Repository: flame-banking-identity-management
// Aggregation that cannot be expressed in Sigma:
// Original condition: stage1_sim_change | followed_by stage2_password_reset | followed_by stage3_high_value_action on user_id within 24h
(event_type="phone_number_change" OR event_type="sim_swap" OR event_type="mobile_update")
event_type="password_reset"
reset_method="sms_otp"
(event_type="wire_transfer" OR event_type="beneficiary_add" OR event_type="address_change" OR event_type="email_change")
transaction_amount>=1000
// Sequential correlation — use LogScale sequence detection
// Correlate stages sequentially on on within 24h

// LogScale LQL for Instant Payment Velocity Spike Above 30-Day Baseline
// Repository: flame-banking-transaction-monitoring
// Aggregation that cannot be expressed in Sigma:
// Original condition: selection | count() by account_id | compare(op=gt, period=30d, stdev=3)
event_type="instant_payment_initiated"
(payment_rail="ZELLE" OR payment_rail="FEDNOW" OR payment_rail="RTP" OR payment_rail="ACH_SAMEDAY")
// Aggregation logic from original condition:
// selection | count() by account_id | compare(op=gt, period=30d, stdev=3)

// LogScale LQL for Cross-Platform Deposit and Withdrawal Chain
// Repository: flame-banking-transaction-monitoring
// Aggregation that cannot be expressed in Sigma:
// Original condition: (selection_inbound and selection_outbound and filter_amount) | temporal(ordered=true, maxspan=4h, by=account_id)
event_type="payment_received"
(inbound_rail="ACH_IN" OR inbound_rail="WIRE_IN" OR inbound_rail="RTP_IN" OR inbound_rail="FEDNOW_IN")
event_type="instant_payment_initiated"
(outbound_rail="ZELLE" OR outbound_rail="FEDNOW" OR outbound_rail="RTP" OR outbound_rail="ACH_SAMEDAY")
outbound_amount_pct_of_inbound>=80
// Temporal ordered correlation — use join() in LogScale
| join({...}, field=account_id, mode=inner)

// LogScale LQL for Repeated A2A Payments at Maximum Per-Transaction Limit
// Repository: flame-banking-a2a-processing
// Aggregation that cannot be expressed in Sigma:
// Original condition: selection and filter_at_limit | count() by account_id > 3
event_type="a2a_payment_initiated"
(payment_rail="ZELLE" OR payment_rail="FEDNOW" OR payment_rail="RTP" OR payment_rail="ACH_SAMEDAY")
amount_pct_of_rail_limit>=95
| groupBy(account_id, function=count(as=event_count))
| event_count > 3

// LogScale LQL for New Account Sending Multiple Instant Payments
// Repository: flame-banking-instant-payments
// Aggregation that cannot be expressed in Sigma:
// Original condition: selection and filter_new_account | count() by account_id > 5
event_type="instant_payment_initiated"
(payment_rail="ZELLE" OR payment_rail="FEDNOW" OR payment_rail="RTP" OR payment_rail="ACH_SAMEDAY")
account_age_days<30
| groupBy(account_id, function=count(as=event_count))
| event_count > 5

// LogScale LQL for Zelle Recipient Enumeration via Multiple Failed Lookups
// Repository: flame-banking-a2a-processing
// Aggregation that cannot be expressed in Sigma:
// Original condition: selection | count() by account_id > 10
event_type="zelle_recipient_lookup"
lookup_result="not_found"
| groupBy(account_id, function=count(as=event_count))
| event_count > 10

// LogScale LQL for Real-Time Payment Followed by Immediate Refund or Return Request
// Repository: flame-banking-instant-payments
// Aggregation that cannot be expressed in Sigma:
// Original condition: (selection_payment and selection_refund) | temporal(ordered=true, maxspan=2h, by=payment_reference_id)
event_type="instant_payment_completed"
(payment_rail="RTP" OR payment_rail="FEDNOW")
(event_type="refund_request" OR event_type="return_request" OR event_type="rrof_submitted")
// Temporal ordered correlation — use join() in LogScale
| join({...}, field=payment_reference_id, mode=inner)

// LogScale LQL for Multi-Operator Behavioral Shift — Timezone and Communication Anomaly
// Repository: flame-identity-platform-authentication
// Aggregation that cannot be expressed in Sigma:
// Original condition: selection | count(distinct src_timezone) by user_id > 2
event_type="user_login"
| groupBy(user_id, function=[count(as=event_count), collect(src_timezone)])
| event_count > 2

// LogScale LQL for Salary Direct Deposit Rapid Cryptocurrency Conversion
// Repository: flame-banking-transaction-monitoring
// Aggregation that cannot be expressed in Sigma:
// Original condition: selection_deposit | near selection_conversion
transaction_type="ACH_IN"
transaction_category="payroll"
(outbound_type="crypto_exchange" OR outbound_type="p2p_crypto" OR outbound_type="wire_to_exchange")
time_since_deposit_hours<=48
// Temporal correlation — use join() or selfJoinFilter() in LogScale
// to correlate the selection events within the timeframe
| selfJoinFilter(account_id, where=[...])

// LogScale LQL for Automated Mule Account Creation Velocity
// Repository: flame-banking-account-onboarding
// Aggregation that cannot be expressed in Sigma
application_duration_seconds<120 OR mouse_events_count=0 OR scroll_events_count=0
| groupBy([device_fingerprint, ip_address], function=[
    count(as=app_count),
    countDistinct(applicant_id, as=unique_applicants),
    collect(applicant_id),
    avg(application_duration_seconds, as=avg_duration),
    min(application_duration_seconds, as=min_duration),
    sum(mouse_events_count, as=total_mouse_events)
  ])
| app_count>3 OR (avg_duration<120 AND total_mouse_events=0)
| case {
    app_count>10 | risk_level:="critical";
    app_count>5 | risk_level:="high";
    app_count>3 | risk_level:="medium";
  }

// LogScale LQL for Keitaro/Binom TDS Abuse Infrastructure Detection
// Repository: flame-proxy-http-log
// HTTP redirect chain analysis for TDS abuse patterns
(url_query=/click_id=|campaign_id=|keitaro|binom|cnv_id=/)
OR (url_path=/\/tracker\/|\/click\/|\/go\/|\/click\.php/)
| selfJoinFilter(session_id, where=[{url_query=/keitaro/ OR url_path=/\/tracker\//} {url_query=/binom/ OR url_path=/\/click\.php/}])
| groupBy([session_id, src_ip], function=[
    count(as=redirect_count),
    collect([url, final_destination])
  ])
| redirect_count>=3
